#!/bin/bash
# Set up and submit a debug run for mean_state_nudge (rep_01, 64x64 grid).
#
# Usage:
#   ./submit_debug_mean_state_nudge.sh --timescale 3600 \\
#       --nudge-profiles $SCRATCH/CASS_LES/experiments/mean_state_nudge/nudge_profiles.nc
#
# Requires: nudge_profiles.nc generated by extract_nudge_profiles.py
set -euo pipefail

TIMESCALE=""
NUDGE_PROFILES=""
while [[ $# -gt 0 ]]; do
    case "$1" in
        --timescale)      TIMESCALE="$2";      shift 2 ;;
        --nudge-profiles) NUDGE_PROFILES="$2"; shift 2 ;;
        *) echo "Unknown argument: $1"; exit 1 ;;
    esac
done

if [[ -z "$TIMESCALE" || -z "$NUDGE_PROFILES" ]]; then
    echo "Usage: $0 --timescale SECONDS --nudge-profiles PATH"
    exit 1
fi

SCRATCH=${SCRATCH:-/pscratch/sd/m/mpowell}
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SBATCH_DEBUG="/global/homes/m/mpowell/repos/microhh/cases/cass/shared/sbatch_debug.sh"

mkdir -p "$SCRATCH/CASS_LES/logs"

echo "Setting up debug mean_state_nudge run (timescale=${TIMESCALE}s)..."
python "$SCRIPT_DIR/setup_mean_state_nudge.py" \
    --timescale "$TIMESCALE" \
    --nudge-profiles "$NUDGE_PROFILES" \
    --debug

LABEL="nudge_${TIMESCALE}s"
SIM_DIR="$SCRATCH/CASS_LES/debug/mean_state_nudge/$LABEL/raytracer/rep_01"

sbatch \
    --constraint="gpu&hbm80g" \
    --job-name="dbg_msn_rt_${TIMESCALE}" \
    --export=ALL,SIM_DIR="$SIM_DIR" \
    "$SBATCH_DEBUG"

echo "Submitted debug mean_state_nudge/$LABEL raytracer/rep_01"
